// Shortcode for easy icon usage: [icon name="play" class="w-6 h-6"]
function viralay_icon_shortcode($atts) {
    $atts = shortcode_atts(array(
        'name' => 'play',
        'class' => 'w-6 h-6'
    ), $atts);
    
    return viralay_get_svg_icon($atts['name'], $atts['class']);
}
add_shortcode('icon', 'viralay_icon_shortcode');
